FEE = 3000

# 요구: 수량 1~4는 배송비 FEE, 5~9는 0, 그 밖은 '거절'이에요.
def ship_fee(qty):
    if qty < 1:
        return '거절'
    if qty < 5:
        return FEE
    return 0

# (구간 이름, 가장 작은 값, 가장 큰 값, 요구의 결과)
PARTS = [('0 이하', -99, 0, '거절'), ('1~4', 1, 4, FEE), ('5~9', 5, 9, 0), ('10 이상', 10, 99, '거절')]

# 검사할 수량이에요.
inputs = [2, 3, 4]

for name, lo, hi, want in PARTS:
    picked = [q for q in inputs if lo <= q <= hi]
    if not picked:
        print(name, '검사 안 함')
    elif all(ship_fee(q) == want for q in picked):
        print(name, '통과')
    else:
        print(name, '실패')
print(f'검사한 값 {len(inputs)}개')

